import React, { useState } from "react";
import { Link } from "gatsby";

import { SectionHead } from "./Chrome";
import { SERVICES } from "./content";

/** The Adina template's two-path arrow: one slides out, the other slides in. */
function Arrow() {
  const d = "M1.018 10.009 0 8.991l7.569-7.582H1.723L1.737 0h8.26v8.274H8.574l.013-5.847Z";
  return (
    <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true">
      <path d={d} />
      <path d={d} />
    </svg>
  );
}

/**
 * Five columns over one full-bleed photograph, the strip from the Adina
 * template. Hovering a column fades the photograph to that service, raises its
 * title, and reveals the description, button and ghost number. The photograph
 * stays on the last column hovered. Below 1200px there is no hover, so each
 * column carries its own picture and text.
 */
export default function Services() {
  const [active, setActive] = useState(1);

  return (
    <section id="services" className="sbs-section" style={{ paddingBottom: 0 }} aria-labelledby="sbs-services-title">
      <div className="sbs-wrap sbs-svchead">
        <SectionHead
          eyebrow="What Sajra does"
          title={
            <span id="sbs-services-title">
              Buy, sell, invest,
              <br />
              with a builder’s eye
            </span>
          }
        />
        <p>
          Whether it is a first home, the one you are ready to sell, or an investment you are building toward, the
          process stays smooth, strategic and genuinely enjoyable.
        </p>
      </div>

      <div className="sbs-svc">
        <div className="sbs-svc__bg" aria-hidden="true">
          {SERVICES.map((service, index) => (
            <div
              key={service.tag}
              className={`sbs-svc__img${index === active ? " is-on" : ""}`}
              style={{ backgroundImage: `url(${service.image})` }}
            />
          ))}
        </div>

        <div className="sbs-svc__cols">
          {SERVICES.map((service, index) => (
            <div
              key={service.tag}
              className="sbs-svc__col"
              onMouseEnter={() => setActive(index)}
              onFocus={() => setActive(index)}
            >
              <div className="sbs-svc__thumb" style={{ backgroundImage: `url(${service.image})` }} aria-hidden="true" />
              <div className="sbs-svc__wrap">
                <span className="sbs-svc__tag">{service.tag}</span>
                <h3 className="sbs-svc__num" aria-hidden="true">
                  {String(index + 1).padStart(2, "0")}
                </h3>
                <div className="sbs-svc__content">
                  <h3 className="sbs-svc__title">
                    <Link to={`/contact/?topic=${service.topic}`}>{service.title}</Link>
                  </h3>
                  <div className="sbs-svc__inner">
                    <p className="sbs-svc__para">{service.text}</p>
                    <Link to={`/contact/?topic=${service.topic}`} className="sbs-svc__btn">
                      Talk to Sajra
                      <Arrow />
                    </Link>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
